callbacks.text:
transferData -> {
                transferData.setDestinationAccountExternalId(
                    getExternalAccountId(transferData.getDestinationAccountId()));
                log.info(
                    "Account {} / {} will be used for the transfer.",
                    transferData.getDestinationAccountId(),
                    transferData.getDestinationAccountExternalId());
              }

(key, value) -> {
          if (CAMEL_CASE_PATTERN.matcher(key).matches()) {
            return;
          }

          String alternativeKey = CaseUtils.toCamelCase(key, false, '_', ' ').trim();
          if (key.contains(" ")) {
            result.remove(key);
          }
          if (!StringUtils.isAllBlank(alternativeKey)) {
            result.putIfAbsent(CaseUtils.toCamelCase(key, false, '_', ' '), value);
          }
        }
